import"./scan_settings_section.js";import"./strings.m.js";import{assert}from"chrome://resources/ash/common/assert.js";import{I18nMixin}from"chrome://resources/ash/common/cr_elements/i18n_mixin.js";import{PolymerElement}from"chrome://resources/polymer/v3_0/polymer/polymer_bundled.min.js";import{getTemplate}from"./color_mode_select.html.js";import{ColorMode}from"./scanning.mojom-webui.js";import{alphabeticalCompare,getColorModeString}from"./scanning_app_util.js";import{SelectMixin}from"./select_mixin.js";const DEFAULT_COLOR_MODE=ColorMode.kColor;const ColorModeSelectElementBase=SelectMixin(I18nMixin(PolymerElement));export class ColorModeSelectElement extends ColorModeSelectElementBase{static get is(){return"color-mode-select"}static get template(){return getTemplate()}getOptionAtIndex(index){assert(index<this.options.length);return this.options[index].toString()}getColorModeAsString(mojoColorMode){return getColorModeString(mojoColorMode)}sortOptions(){this.options.sort(((a,b)=>alphabeticalCompare(getColorModeString(a),getColorModeString(b))))}isDefaultOption(option){return option===DEFAULT_COLOR_MODE}}customElements.define(ColorModeSelectElement.is,ColorModeSelectElement);